#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Every SKU that moved appears with its net (receipts minus shipments), and
# catalog SKUs that had no movements appear with net 0 (SKU-9 is in the catalog).
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) print sku, net[sku] }' movements.log
    printf 'SKU-9 0\n'
} | sort > stock.txt
